-- Verifica rapida rollback: timer iniziali, modifica corrente, originale immutabile.
begin;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
set local role authenticated;
do $test$
declare changes jsonb := '[{"tabella": "esercizi", "versione_attesa": 0, "dati": {"id": "00000000-0000-0000-0000-000000000001", "nome": "Piegamenti demo", "istruzioni": "Dati fittizi per verificare il software.", "categoria": "ripetizioni", "convenzione_carico": null, "convenzione_ripetizioni": "totali"}}, {"tabella": "esercizi", "versione_attesa": 0, "dati": {"id": "00000000-0000-0000-0000-000000000002", "nome": "Curl demo", "istruzioni": "Dati fittizi per verificare il software.", "categoria": "ripetizioni_carico", "convenzione_carico": "totale", "convenzione_ripetizioni": "totali"}}, {"tabella": "esercizi", "versione_attesa": 0, "dati": {"id": "00000000-0000-0000-0000-000000000003", "nome": "Plank demo", "istruzioni": "Dati fittizi per verificare il software.", "categoria": "durata", "convenzione_carico": null, "convenzione_ripetizioni": null}}, {"tabella": "esercizi", "versione_attesa": 0, "dati": {"id": "00000000-0000-0000-0000-000000000004", "nome": "Tenuta demo", "istruzioni": "Dati fittizi per verificare il software.", "categoria": "durata_carico", "convenzione_carico": "totale", "convenzione_ripetizioni": null}}, {"tabella": "esercizi", "versione_attesa": 0, "dati": {"id": "00000000-0000-0000-0000-000000000005", "nome": "Camminata demo", "istruzioni": "Dati fittizi per verificare il software.", "categoria": "distanza_durata", "convenzione_carico": null, "convenzione_ripetizioni": null}}, {"tabella": "schede", "versione_attesa": 0, "dati": {"id": "00000000-0000-0000-0000-000000000065", "nome": "Scheda dimostrativa", "note": "Cinque categorie, nessuna prescrizione personale."}}, {"tabella": "allenamenti", "versione_attesa": 0, "dati": {"id": "00000000-0000-0000-0000-000000000066", "nome": "Allenamento di prova", "note": "", "scheda_id": "00000000-0000-0000-0000-000000000065", "posizione": 1}}, {"tabella": "esercizi_allenamento", "versione_attesa": 0, "dati": {"id": "00000000-0000-0000-0000-00000000000b", "esercizio_id": "00000000-0000-0000-0000-000000000001", "allenamento_id": "00000000-0000-0000-0000-000000000066", "posizione": 1, "note": "", "ai_recupero_serie_secondi": 10, "ai_recupero_esercizio_secondi": 15, "corrente_recupero_serie_secondi": 10, "corrente_recupero_esercizio_secondi": 15, "ai_serie": 3, "ai_ripetizioni": 8, "corrente_serie": 3, "corrente_ripetizioni": 8}}, {"tabella": "esercizi_allenamento", "versione_attesa": 0, "dati": {"id": "00000000-0000-0000-0000-00000000000c", "esercizio_id": "00000000-0000-0000-0000-000000000002", "allenamento_id": "00000000-0000-0000-0000-000000000066", "posizione": 2, "note": "", "ai_recupero_serie_secondi": 10, "ai_recupero_esercizio_secondi": 15, "corrente_recupero_serie_secondi": 10, "corrente_recupero_esercizio_secondi": 15, "ai_serie": 3, "ai_ripetizioni": 8, "ai_carico_kg": 2.5, "corrente_serie": 3, "corrente_ripetizioni": 8, "corrente_carico_kg": 2.5}}, {"tabella": "esercizi_allenamento", "versione_attesa": 0, "dati": {"id": "00000000-0000-0000-0000-00000000000d", "esercizio_id": "00000000-0000-0000-0000-000000000003", "allenamento_id": "00000000-0000-0000-0000-000000000066", "posizione": 3, "note": "", "ai_recupero_serie_secondi": 10, "ai_recupero_esercizio_secondi": 15, "corrente_recupero_serie_secondi": 10, "corrente_recupero_esercizio_secondi": 15, "ai_serie": 3, "ai_durata_secondi": 30, "corrente_serie": 3, "corrente_durata_secondi": 30}}, {"tabella": "esercizi_allenamento", "versione_attesa": 0, "dati": {"id": "00000000-0000-0000-0000-00000000000e", "esercizio_id": "00000000-0000-0000-0000-000000000004", "allenamento_id": "00000000-0000-0000-0000-000000000066", "posizione": 4, "note": "", "ai_recupero_serie_secondi": 10, "ai_recupero_esercizio_secondi": 15, "corrente_recupero_serie_secondi": 10, "corrente_recupero_esercizio_secondi": 15, "ai_serie": 3, "ai_durata_secondi": 30, "ai_carico_kg": 2.5, "corrente_serie": 3, "corrente_durata_secondi": 30, "corrente_carico_kg": 2.5}}, {"tabella": "esercizi_allenamento", "versione_attesa": 0, "dati": {"id": "00000000-0000-0000-0000-00000000000f", "esercizio_id": "00000000-0000-0000-0000-000000000005", "allenamento_id": "00000000-0000-0000-0000-000000000066", "posizione": 5, "note": "", "ai_recupero_serie_secondi": 10, "ai_recupero_esercizio_secondi": 15, "corrente_recupero_serie_secondi": 10, "corrente_recupero_esercizio_secondi": 15, "ai_distanza_metri": 1000, "ai_durata_secondi": 30, "corrente_distanza_metri": 1000, "corrente_durata_secondi": 30}}]'::jsonb; receipt jsonb; plan uuid; entry uuid;
begin
 receipt:=public.salva_gruppo(gen_random_uuid(),changes);
 select id into plan from public.schede limit 1;
 select id into entry from public.esercizi_allenamento order by posizione limit 1;
 perform public.salva_gruppo(gen_random_uuid(),jsonb_build_array(
 jsonb_build_object('tabella','schede','versione_attesa',1,'dati',jsonb_build_object('id',plan,'revisione',2)),
 jsonb_build_object('tabella','esercizi_allenamento','versione_attesa',1,'dati',jsonb_build_object('id',entry,'corrente_recupero_serie_secondi',60,'corrente_recupero_esercizio_secondi',90))));
 if not exists(select 1 from public.esercizi_allenamento where id=entry and ai_recupero_serie_secondi=10 and corrente_recupero_serie_secondi=60) then raise exception 'Recuperi correnti o originali errati'; end if;
 begin
 perform public.salva_gruppo(gen_random_uuid(),jsonb_build_array(
 jsonb_build_object('tabella','schede','versione_attesa',2,'dati',jsonb_build_object('id',plan,'revisione',3)),
 jsonb_build_object('tabella','esercizi_allenamento','versione_attesa',2,'dati',jsonb_build_object('id',entry,'ai_recupero_serie_secondi',20))));
 raise exception 'TEST FALLITO: originale AI modificato';
 exception when raise_exception then if sqlerrm like 'TEST FALLITO%' then raise; end if; end;
 begin
 perform public.salva_gruppo(gen_random_uuid(),jsonb_build_array(
 jsonb_build_object('tabella','schede','versione_attesa',2,'dati',jsonb_build_object('id',plan,'revisione',3)),
 jsonb_build_object('tabella','esercizi_allenamento','versione_attesa',2,'dati',jsonb_build_object('id',entry,'corrente_recupero_serie_secondi',-1))));
 raise exception 'TEST FALLITO: recupero negativo accettato';
 exception when check_violation then null; end;
end $test$;
rollback;
